polygons<-function(z,factor=1){if(nrow(z)==0)return(data.table());v<-rbind(-basis[1,]/2-basis[2,]/2,basis[1,]/2-basis[2,]/2,basis[1,]/2+basis[2,]/2,-basis[1,]/2+basis[2,]/2)*factor;k<-rep(seq_len(nrow(z)),each=4);p<-z[k];p[,px:=x_um+rep(v[,1],nrow(z))];p[,py:=-y_um-rep(v[,2],nrow(z))];p[,poly_id:=k];p}
