 q<-rbindlist(list(data.table(x_um=cc$nucleus_x_um,y_um=cc$nucleus_y_um,label=cc$candidate_blca,method='Cell8 BLCA'),data.table(x_um=z$x_um,y_um=z$y_um,label=z$candidate_blca,method='Bin8 BLCA'),data.table(x_um=z$x_um,y_um=z$y_um,label=z$candidate_hpca,method='Bin8 HPCA')),use.names=TRUE);if(!is.null(rt)){rr<-rt[roi==b$roi&qc_keep==TRUE];rr[,label:=ifelse(rctd_status%in%c('singlet','doublet_certain','doublet_uncertain'),as.character(first_type),'Not fitted / reject')];q<-rbind(q,data.table(x_um=rr$x_um,y_um=rr$y_um,label=rr$label,method='RCTD first (ROI)'))};q[,method:=factor(method,levels=c('Cell8 BLCA','Bin8 BLCA','Bin8 HPCA','RCTD first (ROI)'))];tiles<-polygons(q[method!='Cell8 BLCA']);p<-ggplot(q,aes(x_um,-y_um))+annotation_raster(im,xlim[1],xlim[2],ylim[1],ylim[2])+annotation_raster(bd,xlim[1],xlim[2],ylim[1],ylim[2])+geom_polygon(data=tiles,aes(px,py,group=poly_id,fill=label),alpha=.8,inherit.aes=FALSE)+geom_point(data=q[method=='Cell8 BLCA'],aes(fill=label),shape=21,color='black',stroke=.35,size=1.25)+facet_wrap(~method,nrow=1)+scale_fill_manual(values=colors,name='Candidate')+scale_x_continuous(n.breaks=3)+coord_fixed(xlim=xlim,ylim=ylim,expand=FALSE)+jin_theme()+labs(x='Original x (um)',y='- Original y (um)');export(p,paste0('ROI_candidates_',b$roi),16,4.8,14.5)
 v<-rx[roi==b$roi];v[,method:=factor(unit,levels=c('HE','raw_2um','cell4','cell8','bin8'),labels=c('H&E + v2 boundaries','Raw 2 um','Cell 4 um','Cell 8 um','Fixed bin 8 um'))];blank<-data.table(method=factor('H&E + v2 boundaries',levels=levels(v$method)),x_um=mean(xlim),y_um=-mean(ylim));t2<-polygons(v[unit=='raw_2um'],.25);t8<-polygons(v[unit=='bin8']);t8[,poly_id:=poly_id+nrow(t2)];tt<-rbind(t2,t8);signalcol<-c('Epithelial panel'='#f5b264','Collagen panel'='#57c1b5','Both panels'='#6a3d9a','Neither panel'='#bdbdbd');p<-ggplot(v,aes(x_um,-y_um))+annotation_raster(im,xlim[1],xlim[2],ylim[1],ylim[2])+annotation_raster(bd,xlim[1],xlim[2],ylim[1],ylim[2])+geom_blank(data=blank)+geom_polygon(data=tt,aes(px,py,group=poly_id,fill=signal_category),inherit.aes=FALSE,alpha=.8)+geom_point(data=v[unit%in%c('cell4','cell8')],aes(fill=signal_category),shape=21,color='black',stroke=.35,size=1.3)+facet_wrap(~method,nrow=1,drop=FALSE)+scale_fill_manual(values=signalcol,name='Raw panel UMI > 0')+scale_x_continuous(n.breaks=3)+coord_fixed(xlim=xlim,ylim=ylim,expand=FALSE)+jin_theme()+labs(x='Original x (um)',y='- Original y (um)');p$layers[[4]]<-ggrastr::rasterise(p$layers[[4]],dpi=300);export(p,paste0('ROI_raw_signals_',b$roi),18,4.8,16.5)
}
